'use strict';
const API_URL='https://script.google.com/macros/s/AKfycbwd5x_8gPAzXMeP4TZPxLQQABisZ6Zn4lmGmzhfUsg83Z4xdnNY2dqb5KdZvRhGm4M/exec';
const $=id=>document.getElementById(id);
const esc=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
const cleanPhone=v=>String(v||'').replace(/\D/g,'').slice(-10);
const money=v=>'₹'+Number(v||0).toLocaleString('en-IN',{maximumFractionDigits:2});
const WINGS=['Real Estate','Travel','Education & Admissions','Consultancy & Business Services','Events & Weddings','Membership','General / Other'];
const STATUSES=['NEW','CONTACTED','FOLLOW UP','IN PROGRESS','CONVERTED','NOT INTERESTED'];
const state={loginType:'agent',role:null,token:null,user:null,admin:{inquiries:[],agents:[],calling:[],commissions:[],distribution:[],trash:[]},agent:{leads:[],commissions:[],calling:[],shared:null},view:'home'};
let toastTimer=null;
function toast(msg){const t=$('toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2600)}
function busy(btn,on,text='Working...'){if(!btn)return;if(on){btn.dataset.old=btn.textContent;btn.disabled=true;btn.textContent=text}else{btn.disabled=false;btn.textContent=btn.dataset.old||btn.textContent}}
async function api(action,payload={}){const body={...payload,action};let r;try{r=await fetch(API_URL+'?action='+encodeURIComponent(action)+'&_='+Date.now(),{method:'POST',cache:'no-store',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify(body)})}catch(e){throw new Error('Network error. Check internet connection.')}let data;try{data=await r.json()}catch(e){throw new Error('Server returned an invalid response.')}if(!data.success&&/session/i.test(data.message||'')){logout(true);throw new Error('Session expired. Please login again.')}return data}
function storeSession(){sessionStorage.setItem('madhyumMobileSession',JSON.stringify({role:state.role,token:state.token,user:state.user}))}
function restoreSession(){try{const s=JSON.parse(sessionStorage.getItem('madhyumMobileSession')||'null');if(s&&s.role&&s.token){state.role=s.role;state.token=s.token;state.user=s.user;return true}}catch(_){}return false}
function logout(silent=false){sessionStorage.removeItem('madhyumMobileSession');state.role=null;state.token=null;state.user=null;$('appView').classList.add('hidden');$('loginView').classList.remove('hidden');if(!silent)toast('Logged out')}
function statusBadge(s){const k=String(s||'NEW').toLowerCase().replace(/\s+/g,'-');return `<span class="status s-${['new','contacted','follow-up','in-progress','converted','not-interested'].includes(k)?k:'default'}">${esc(s||'NEW')}</span>`}
function followClass(d,status){if(!d||['CONVERTED','NOT INTERESTED'].includes(String(status||'').toUpperCase()))return'';const a=new Date(d+'T00:00:00'),b=new Date();b.setHours(0,0,0,0);return a<b?'overdue':a.getTime()===b.getTime()?'due':''}
function callActions(mobile){const m=cleanPhone(mobile);return m?`<a class="act-dark" href="tel:${m}">Call</a><a class="act-green" target="_blank" rel="noopener" href="https://wa.me/91${m}">WhatsApp</a>`:''}
function openModal(title,html,actions=''){ $('modalRoot').innerHTML=`<div class="modal-backdrop" id="modalBackdrop"><div class="modal-sheet"><div class="modal-grip"></div><div class="modal-head"><h3>${esc(title)}</h3><button class="modal-close" id="modalClose">×</button></div>${html}${actions}</div></div>`;$('modalClose').onclick=closeModal;$('modalBackdrop').onclick=e=>{if(e.target.id==='modalBackdrop')closeModal()}}
function closeModal(){$('modalRoot').innerHTML=''}
function setLoginType(type){state.loginType=type;$('agentLoginTab').classList.toggle('active',type==='agent');$('adminLoginTab').classList.toggle('active',type==='admin');$('loginId').placeholder=type==='admin'?'Enter Admin ID':'Enter Agent / BDM ID'}
$('agentLoginTab').onclick=()=>setLoginType('agent');$('adminLoginTab').onclick=()=>setLoginType('admin');$('togglePassword').onclick=()=>{const p=$('loginPassword');p.type=p.type==='password'?'text':'password'};
$('loginForm').onsubmit=async e=>{e.preventDefault();const btn=$('loginButton'),id=$('loginId').value.trim().toUpperCase(),password=$('loginPassword').value;if(!id||!password)return;busy(btn,true,'Signing in...');$('loginMessage').textContent='';try{const action=state.loginType==='admin'?'adminLogin':'agentLogin';const payload=state.loginType==='admin'?{adminId:id,password}:{agentId:id,password};const r=await api(action,payload);if(!r.success)throw new Error(r.message||'Login failed.');state.role=state.loginType==='admin'?'admin':'agent';state.token=r.token;state.user=r.admin||r.agent;storeSession();await startApp()}catch(err){$('loginMessage').textContent=err.message}finally{busy(btn,false)}};
function navConfig(){return state.role==='admin'?[['home','⌂','Home'],['leads','◎','Leads'],['agents','♟','Agents'],['calling','☎','Calling'],['more','•••','More']]:[['home','⌂','Home'],['leads','◎','Leads'],['add','＋','Add'],['followups','◷','Follow Up'],['more','•••','More']]}
function renderNav(){const nav=$('bottomNav');nav.innerHTML=navConfig().map(([v,i,l])=>`<button class="nav-btn ${v===state.view?'active':''} ${v==='add'?'add':''}" data-view="${v}"><span>${i}</span>${l}</button>`).join('');nav.querySelectorAll('button').forEach(b=>b.onclick=()=>navigate(b.dataset.view))}
function titleFor(v){const map={home:'Dashboard',leads:'Leads',agents:'Agents & BDM',calling:'Calling Data',add:'Add Lead',followups:'Follow Ups',more:'More',commission:'Commissions',shared:'Shared Data',distribution:'Data Distribution',dispose:'Dispose',profile:'Profile',adminCommission:'Commissions'};return map[v]||'MADHYUM CRM'}
async function navigate(v){state.view=v;$('screenTitle').textContent=titleFor(v);renderNav();const mc=$('mainContent');mc.innerHTML='<div class="loading-skeleton"></div><div style="height:10px"></div><div class="loading-skeleton"></div>';try{if(state.role==='admin')await renderAdmin(v);else await renderAgent(v)}catch(e){mc.innerHTML=`<div class="section-card"><div class="empty">${esc(e.message)}</div></div>`}}
async function startApp(){$('loginView').classList.add('hidden');$('appView').classList.remove('hidden');$('userLine').textContent=state.role==='admin'?`${state.user?.name||''} • ${state.user?.adminId||''}`:`${state.user?.name||''} • ${state.user?.agentId||''}`;state.view='home';renderNav();await navigate('home')}
$('refreshButton').onclick=()=>navigate(state.view);

// AGENT / BDM
async function loadAgentDashboard(){const r=await api('agentDashboard',{token:state.token});if(!r.success)throw new Error(r.message||'Unable to load dashboard.');state.user=r.agent||state.user;state.agent.leads=Array.isArray(r.leads)?r.leads:[];state.agent.commissions=Array.isArray(r.commissions)?r.commissions:[];storeSession();return r}
function leadCard(l,admin=false){const id=l.leadId||l.inquiryId||'',mobile=l.mobile||'',req=l.requirement||'General / Other',agent=l.agentId||l.lgId||'';return `<article class="item-card ${followClass(l.followUp,l.status)}"><div class="item-top"><div><div class="item-title">${esc(l.name||'Unnamed')}</div><div class="item-id">${esc(id)}</div></div>${statusBadge(l.status)}</div><div class="item-meta"><span>📱 ${esc(mobile||'—')}</span><span>◈ ${esc(req)}</span>${agent?`<span>Agent: ${esc(agent)}</span>`:''}${l.followUp?`<span>Follow-up: ${esc(l.followUp)}</span>`:''}</div>${l.details?`<div class="item-note">${esc(l.details)}</div>`:''}<div class="item-actions">${callActions(mobile)}<button class="act-gold edit-lead" data-id="${esc(id)}">Edit</button>${admin?`<button class="act-red dispose-lead" data-id="${esc(id)}" data-type="${esc(l.recordType||'WEBSITE')}">Dispose</button>`:''}</div></article>`}
async function renderAgent(v){if(v==='home'){await loadAgentDashboard();renderAgentHome();return}if(v==='leads'){if(!state.agent.leads.length)await loadAgentDashboard();renderAgentLeads();return}if(v==='add'){renderAddLead();return}if(v==='followups'){if(!state.agent.leads.length)await loadAgentDashboard();renderFollowups();return}if(v==='more'){renderAgentMore();return}if(v==='commission'){if(!state.agent.commissions.length)await loadAgentDashboard();renderAgentCommission();return}if(v==='calling'){await loadAgentCalling();renderAgentCalling();return}if(v==='shared'){await loadAgentShared();renderAgentShared();return}if(v==='profile'){renderProfile();return}}
function renderAgentHome(){const leads=state.agent.leads,count=s=>leads.filter(x=>String(x.status||'').toUpperCase()===s).length,isBdm=String(state.user?.role||'').toUpperCase()==='EMPLOYEE';$('mainContent').innerHTML=`<section class="hero"><div class="eyebrow">${isBdm?'BDM / EMPLOYEE':'AGENT / BDE'}</div><h3>Hello, ${esc(state.user?.name||'')}</h3><p>Manage leads, follow-ups, calling data and earnings from one place.</p><div class="hero-action"><button class="primary-btn" onclick="navigate('add')">+ Add Lead</button></div></section><section class="metric-grid"><div class="metric full" onclick="navigate('leads')"><div><div class="label">TOTAL LEADS</div><div class="value">${leads.length}</div></div><span>→</span></div><div class="metric" onclick="filterAgentStatus('NEW')"><div class="label">NEW</div><div class="value">${count('NEW')}</div></div><div class="metric" onclick="navigate('followups')"><div class="label">FOLLOW UP</div><div class="value">${count('FOLLOW UP')}</div></div><div class="metric" onclick="filterAgentStatus('IN PROGRESS')"><div class="label">IN PROGRESS</div><div class="value">${count('IN PROGRESS')}</div></div><div class="metric" onclick="filterAgentStatus('CONVERTED')"><div class="label">CONVERTED</div><div class="value">${count('CONVERTED')}</div></div></section><section class="section-card"><div class="section-head"><h3>Recent Leads</h3><button class="link" onclick="navigate('leads')">View all</button></div><div class="list">${leads.slice(0,4).map(l=>leadCard(l)).join('')||'<div class="empty">No leads yet.</div>'}</div></section>`;bindLeadButtons(false)}
window.filterAgentStatus=function(s){state.agentFilter=s;navigate('leads')}
function renderAgentLeads(){const mc=$('mainContent');mc.innerHTML=`<div class="toolbar"><input class="input" id="agentSearch" placeholder="Search name, mobile or lead ID"><select class="select" id="agentWing"><option value="">All requirements</option>${WINGS.map(w=>`<option>${w}</option>`).join('')}</select><select class="select" id="agentStatus"><option value="">All statuses</option>${STATUSES.map(s=>`<option>${s}</option>`).join('')}</select></div><div id="agentLeadList" class="list"></div>`;if(state.agentFilter){$('agentStatus').value=state.agentFilter;state.agentFilter=''};const run=()=>{const q=$('agentSearch').value.toLowerCase(),w=$('agentWing').value,s=$('agentStatus').value;const rows=state.agent.leads.filter(l=>(!q||[l.leadId,l.name,l.mobile].join(' ').toLowerCase().includes(q))&&(!w||l.requirement===w)&&(!s||String(l.status).toUpperCase()===s));$('agentLeadList').innerHTML=rows.map(l=>leadCard(l)).join('')||'<div class="section-card"><div class="empty">No matching leads.</div></div>';bindLeadButtons(false)};['agentSearch','agentWing','agentStatus'].forEach(id=>$(id).addEventListener(id==='agentSearch'?'input':'change',run));run()}
function renderFollowups(){const today=new Date();today.setHours(0,0,0,0);const rows=state.agent.leads.filter(l=>l.followUp&&!['CONVERTED','NOT INTERESTED'].includes(String(l.status).toUpperCase())).sort((a,b)=>String(a.followUp).localeCompare(String(b.followUp)));$('mainContent').innerHTML=`<section class="section-card"><div class="section-head"><h3>Due & Upcoming</h3><span class="tiny muted">${rows.length} records</span></div><div class="list">${rows.map(l=>leadCard(l)).join('')||'<div class="empty">No follow-ups scheduled.</div>'}</div></section>`;bindLeadButtons(false)}
function renderAddLead(){$('mainContent').innerHTML=`<section class="section-card"><div class="section-head"><h3>New Customer Lead</h3></div><form id="addLeadForm" class="form-grid"><div><label class="field-label">Customer Name</label><input class="input" id="alName" required></div><div><label class="field-label">Mobile</label><input class="input" id="alMobile" inputmode="numeric" maxlength="10" required></div><div><label class="field-label">Email</label><input class="input" id="alEmail" type="email"></div><div><label class="field-label">Wing / Requirement</label><select class="select" id="alWing" required><option value="">Select</option>${WINGS.map(w=>`<option>${w}</option>`).join('')}</select></div><div><label class="field-label">Category / Sub-category</label><input class="input" id="alSub" placeholder="Plot, Hotel, MBBS, GST..."></div><div><label class="field-label">Budget / Range</label><input class="input" id="alBudget"></div><div class="field-full"><label class="field-label">Details</label><textarea class="textarea" id="alDetails"></textarea></div><div class="field-full"><button class="primary-btn" id="addLeadBtn">Add Lead</button><div id="addLeadMsg" class="form-message"></div></div></form></section>`;$('alMobile').oninput=e=>e.target.value=cleanPhone(e.target.value);$('addLeadForm').onsubmit=async e=>{e.preventDefault();const btn=$('addLeadBtn');busy(btn,true,'Adding...');try{const details=[ $('alSub').value.trim()?`Category / Sub-category: ${$('alSub').value.trim()}`:'',$('alBudget').value.trim()?`Budget / Range: ${$('alBudget').value.trim()}`:'',$('alDetails').value.trim()?`Details: ${$('alDetails').value.trim()}`:''].filter(Boolean).join('\n');const r=await api('addAgentLead',{token:state.token,name:$('alName').value.trim(),mobile:cleanPhone($('alMobile').value),email:$('alEmail').value.trim(),requirement:$('alWing').value,details});if(!r.success)throw new Error(r.message||'Unable to add lead.');toast(`Lead ${r.leadId||''} added`);await loadAgentDashboard();navigate('leads')}catch(err){$('addLeadMsg').textContent=err.message}finally{busy(btn,false)}}}
function bindLeadButtons(admin){document.querySelectorAll('.edit-lead').forEach(b=>b.onclick=()=>openLeadEditor(b.dataset.id,admin));if(admin)document.querySelectorAll('.dispose-lead').forEach(b=>b.onclick=()=>disposeLead(b.dataset.type,b.dataset.id))}
function parseDetails(text){const out={sub:'',budget:'',details:''};String(text||'').split(/\r?\n/).forEach(line=>{if(/^Category \/ Sub-category:/i.test(line))out.sub=line.replace(/^.*?:/,'').trim();else if(/^Budget \/ Range:/i.test(line))out.budget=line.replace(/^.*?:/,'').trim();else if(/^Details:/i.test(line))out.details+=(out.details?'\n':'')+line.replace(/^Details:/i,'').trim();else out.details+=(out.details?'\n':'')+line});return out}
function openLeadEditor(id,admin){const l=(admin?state.admin.inquiries:state.agent.leads).find(x=>(x.inquiryId||x.leadId)===id);if(!l)return;const p=parseDetails(l.details);const isAgentRecord=admin&&String(l.recordType||'').toUpperCase()==='AGENT';openModal('Edit Lead',`<div class="form-grid"><div><label class="field-label">Customer</label><input class="input" id="edName" value="${esc(l.name||'')}" ${admin?'disabled':''}></div><div><label class="field-label">Mobile</label><input class="input" id="edMobile" value="${esc(l.mobile||'')}" ${admin?'disabled':''}></div><div><label class="field-label">Requirement</label><select class="select" id="edWing" ${admin?'disabled':''}>${WINGS.map(w=>`<option ${w===l.requirement?'selected':''}>${w}</option>`).join('')}</select></div><div><label class="field-label">Status</label><select class="select" id="edStatus">${STATUSES.map(s=>`<option ${s===String(l.status||'').toUpperCase()?'selected':''} ${!admin&&s==='CONVERTED'&&String(l.status).toUpperCase()!=='CONVERTED'?'disabled':''}>${s}</option>`).join('')}</select></div><div><label class="field-label">Follow-up Date</label><input class="input" id="edFollow" type="date" value="${esc(l.followUp||'')}"></div>${admin&&!isAgentRecord?`<div><label class="field-label">Assigned To</label><input class="input" id="edAssigned" value="${esc(l.assignedTo||'')}"></div>`:''}${!admin?`<div><label class="field-label">Category</label><input class="input" id="edSub" value="${esc(p.sub)}"></div><div><label class="field-label">Budget</label><input class="input" id="edBudget" value="${esc(p.budget)}"></div><div class="field-full"><label class="field-label">Details</label><textarea class="textarea" id="edDetails">${esc(p.details)}</textarea></div>`:''}<div class="field-full"><label class="field-label">Notes</label><textarea class="textarea" id="edNotes">${esc(l.notes||'')}</textarea></div></div>`,`<div class="modal-actions"><button class="ghost-btn" onclick="closeModal()">Cancel</button><button class="primary-btn" id="saveLeadEdit">Save Update</button></div>`);$('saveLeadEdit').onclick=async()=>{const btn=$('saveLeadEdit');busy(btn,true,'Saving...');try{let action,payload;if(admin){action=isAgentRecord?'updateAgentLead':'updateInquiry';payload={token:state.token,inquiryId:id,status:$('edStatus').value,assignedTo:isAgentRecord?'':($('edAssigned')?.value||'').trim(),followUp:$('edFollow').value,notes:$('edNotes').value.trim()}}else{const details=[ $('edSub').value.trim()?`Category / Sub-category: ${$('edSub').value.trim()}`:'',$('edBudget').value.trim()?`Budget / Range: ${$('edBudget').value.trim()}`:'',$('edDetails').value.trim()?`Details: ${$('edDetails').value.trim()}`:''].filter(Boolean).join('\n');action='agentUpdateLead';payload={token:state.token,leadId:id,name:$('edName').value.trim(),mobile:cleanPhone($('edMobile').value),requirement:$('edWing').value,details,status:$('edStatus').value,followUp:$('edFollow').value,notes:$('edNotes').value.trim()}}const r=await api(action,payload);if(!r.success)throw new Error(r.message||'Unable to update lead.');toast('Lead updated');closeModal();admin?await loadAdminDashboard():await loadAgentDashboard();navigate('leads')}catch(e){toast(e.message)}finally{busy(btn,false)}}}
function renderAgentMore(){$('mainContent').innerHTML=`<section class="section-card"><div class="quick-grid"><button class="quick" onclick="navigate('commission')"><strong>₹ My Commission</strong><small>Earnings & payout</small></button><button class="quick" onclick="navigate('calling')"><strong>☎ Calling Data</strong><small>Assigned calling list</small></button><button class="quick" onclick="navigate('shared')"><strong>⇄ Shared Data</strong><small>Director / BDM data</small></button><button class="quick" onclick="navigate('profile')"><strong>♙ Profile</strong><small>ID & reporting</small></button></div></section><section class="section-card danger-zone"><div class="section-head"><h3>Account</h3></div><button class="danger-btn" style="width:100%" onclick="logout()">Logout</button></section>`}
function renderAgentCommission(){const rows=state.agent.commissions;$('mainContent').innerHTML=`<section class="hero"><div class="eyebrow">YOUR EARNINGS</div><h3>${money(rows.reduce((a,c)=>a+Number(c.ownCommission||0),0))}</h3><p>Combined earning shown by the existing MADHYUM commission records.</p></section><div class="list">${rows.map(c=>`<article class="item-card"><div class="item-top"><div><div class="item-title">${esc(c.customerName||'')}</div><div class="item-id">${esc(c.leadId)}</div></div><span class="money">${money(c.ownCommission)}</span></div><div class="item-meta"><span>${esc(c.wing||'')}</span><span>${esc(c.commissionStatus||'')}</span><span>Payment: ${esc(c.paymentDate||'—')}</span></div></article>`).join('')||'<div class="section-card"><div class="empty">No commission records.</div></div>'}</div>`}
async function loadAgentCalling(){const r=await api('agentCallingData',{token:state.token});if(!r.success)throw new Error(r.message||'Unable to load calling data.');state.agent.calling=Array.isArray(r.items)?r.items:[];state.agent.callingMeta=r}
function renderAgentCalling(){const rows=state.agent.calling,team=state.agent.callingMeta?.team||[],isBdm=!!state.agent.callingMeta?.isBdm;$('mainContent').innerHTML=`<div class="toolbar two"><input class="input" id="callSearch" placeholder="Search name, mobile, city"><select class="select" id="callStatusFilter"><option value="">All call status</option><option>CONNECTED</option><option>NOT CONNECTED</option></select></div><div id="callList" class="list"></div>`;const run=()=>{const q=$('callSearch').value.toLowerCase(),s=$('callStatusFilter').value;const filtered=rows.filter(x=>(!q||[x.name,x.mobile,x.city,x.source].join(' ').toLowerCase().includes(q))&&(!s||String(x.callStatus).toUpperCase()===s));$('callList').innerHTML=filtered.map(x=>`<article class="item-card"><div class="item-top"><div><div class="item-title">${esc(x.name||'')}</div><div class="item-id">${esc(x.dataId||'')}</div></div>${statusBadge(x.leadStatus||'NEW')}</div><div class="item-meta"><span>${esc(x.mobile||'—')}</span><span>${esc(x.city||'—')}</span><span>${esc(x.source||'—')}</span></div><div class="form-grid"><div><label class="field-label">Call Status</label><select class="select c-status" data-id="${esc(x.dataId)}"><option value="NOT CONNECTED" ${String(x.callStatus).toUpperCase()==='NOT CONNECTED'?'selected':''}>Not Connected</option><option value="CONNECTED" ${String(x.callStatus).toUpperCase()==='CONNECTED'?'selected':''}>Connected</option></select></div><div><label class="field-label">Lead Status</label><select class="select c-lead" data-id="${esc(x.dataId)}">${STATUSES.map(s=>`<option ${s===String(x.leadStatus||'NEW').toUpperCase()?'selected':''}>${s}</option>`).join('')}</select></div><div><label class="field-label">Follow Up</label><input class="input c-follow" type="date" data-id="${esc(x.dataId)}" value="${esc(x.followUpDate||'')}"></div>${isBdm?`<div><label class="field-label">Assigned To</label><select class="select c-assignee" data-id="${esc(x.dataId)}"><option value="${esc(state.agent.callingMeta.me)}">Self</option>${team.map(a=>`<option value="${esc(a.agentId)}" ${a.agentId===x.assignedTo?'selected':''}>${esc(a.agentId+' — '+a.name)}</option>`).join('')}</select></div>`:''}<div class="field-full"><label class="field-label">Remark</label><input class="input c-remark" data-id="${esc(x.dataId)}" value="${esc(x.remark||'')}"></div></div><div class="item-actions">${callActions(x.mobile)}<button class="act-gold save-call" data-id="${esc(x.dataId)}">Save</button></div></article>`).join('')||'<div class="empty">No calling data.</div>';document.querySelectorAll('.save-call').forEach(b=>b.onclick=()=>saveAgentCalling(b.dataset.id,b))};$('callSearch').oninput=run;$('callStatusFilter').onchange=run;run()}
async function saveAgentCalling(id,btn){const root=btn.closest('.item-card');busy(btn,true,'Saving...');try{const r=await api('agentUpdateCallingData',{token:state.token,dataId:id,assignedTo:root.querySelector('.c-assignee')?.value||state.agent.callingMeta.me,callStatus:root.querySelector('.c-status').value,leadStatus:root.querySelector('.c-lead').value,followUpDate:root.querySelector('.c-follow').value,remark:root.querySelector('.c-remark').value.trim()});if(!r.success)throw new Error(r.message||'Unable to save.');toast('Calling data updated');await loadAgentCalling();renderAgentCalling()}catch(e){toast(e.message)}finally{busy(btn,false)}}
async function loadAgentShared(){const r=await api('agentDataDistribution',{token:state.token});if(!r.success)throw new Error(r.message||'Unable to load shared data.');state.agent.shared=r}
function renderAgentShared(){const r=state.agent.shared||{},received=r.received||[],sent=r.sent||[];$('mainContent').innerHTML=`${r.isBdm?`<section class="section-card"><div class="section-head"><h3>Send to Team Agent</h3></div><div class="form-grid"><div><label class="field-label">Recipient</label><select class="select" id="shareRecipient"><option value="">Select Agent</option>${(r.team||[]).map(a=>`<option value="${esc(a.agentId)}">${esc(a.agentId+' — '+a.name)}</option>`).join('')}</select></div><div><label class="field-label">Title</label><input class="input" id="shareTitle"></div><div class="field-full"><label class="field-label">Details</label><textarea class="textarea" id="shareDetails"></textarea></div><div class="field-full"><label class="field-label">Attachment (max 3 MB)</label><input class="input" type="file" id="shareFile"></div><div class="field-full"><button class="primary-btn" id="shareSend">Send to Agent</button></div></div></section>`:''}<section class="section-card"><div class="section-head"><h3>Received Data</h3></div><div class="list">${received.map(x=>sharedCard(x,'received')).join('')||'<div class="empty">No shared data received.</div>'}</div></section>${r.isBdm?`<section class="section-card"><div class="section-head"><h3>Sent to Team</h3></div><div class="list">${sent.map(x=>sharedCard(x,'sent')).join('')||'<div class="empty">No sent records.</div>'}</div></section>`:''}`;document.querySelectorAll('.open-shared').forEach(b=>b.onclick=()=>openSharedFile('agentGetSharedFile',b.dataset.id));if($('shareSend'))$('shareSend').onclick=sendAgentShared}
function sharedCard(x){return `<article class="item-card"><div class="item-top"><div><div class="item-title">${esc(x.title||'Untitled')}</div><div class="item-id">${esc(x.distributionId||'')} • ${esc(x.createdAt||'')}</div></div></div><div class="item-meta"><span>From: ${esc(x.senderId||x.senderName||'—')}</span><span>To: ${esc(x.recipientId||x.recipientName||'—')}</span></div>${x.details?`<div class="item-note">${esc(x.details)}</div>`:''}${x.hasAttachment?`<div class="item-actions"><button class="act-soft open-shared" data-id="${esc(x.distributionId)}">Open ${esc(x.attachmentFileName||'file')}</button></div>`:''}</article>`}
async function filePayload(file,maxMb=3){if(!file)return null;if(file.size>maxMb*1024*1024)throw new Error(`File must be under ${maxMb} MB.`);const b64=await new Promise((res,rej)=>{const fr=new FileReader();fr.onload=()=>res(String(fr.result).split(',')[1]);fr.onerror=rej;fr.readAsDataURL(file)});return {base64:b64,fileName:file.name,mimeType:file.type||'application/octet-stream'} }
async function sendAgentShared(){const btn=$('shareSend');busy(btn,true,'Sending...');try{const f=await filePayload($('shareFile').files[0],3);const r=await api('agentSendData',{token:state.token,recipientId:$('shareRecipient').value,title:$('shareTitle').value.trim(),details:$('shareDetails').value.trim(),file:f});if(!r.success)throw new Error(r.message||'Unable to send.');toast('Data sent');await loadAgentShared();renderAgentShared()}catch(e){toast(e.message)}finally{busy(btn,false)}}
function renderProfile(){$('mainContent').innerHTML=`<section class="hero"><div class="eyebrow">PROFILE</div><h3>${esc(state.user?.name||'')}</h3><p>${esc(state.user?.agentId||state.user?.adminId||'')}</p></section><section class="section-card"><div class="stat-line"><span>Role</span><strong>${esc(state.user?.role||state.role)}</strong></div>${state.user?.mobile?`<div class="stat-line"><span>Mobile</span><strong>${esc(state.user.mobile)}</strong></div>`:''}${state.user?.reportingBdmId?`<div class="stat-line"><span>Reporting BDM</span><strong>${esc(state.user.reportingBdmId)}</strong></div>`:''}</section>`}

// ADMIN
async function loadAdminDashboard(){const r=await api('adminDashboard',{token:state.token});if(!r.success)throw new Error(r.message||'Unable to load admin dashboard.');state.admin.inquiries=Array.isArray(r.inquiries)?r.inquiries:[];state.admin.stats=r.stats||{};return r}
async function renderAdmin(v){if(v==='home'){await Promise.all([loadAdminDashboard(),loadAgents(false)]);renderAdminHome();return}if(v==='leads'){await loadAdminDashboard();renderAdminLeads();return}if(v==='agents'){await loadAgents();renderAgents();return}if(v==='calling'){await loadAdminCalling();renderAdminCalling();return}if(v==='more'){renderAdminMore();return}if(v==='distribution'){await Promise.all([loadAgents(false),loadAdminDistribution()]);renderAdminDistribution();return}if(v==='adminCommission'){await loadAdminCommissions();renderAdminCommissions();return}if(v==='dispose'){await loadAdminTrash();renderAdminTrash();return}if(v==='profile'){renderProfile();return}}
function renderAdminHome(){const s=state.admin.stats||{};$('mainContent').innerHTML=`<section class="hero"><div class="eyebrow">ADMIN CONTROL</div><h3>${esc(state.user?.name||'Director')}</h3><p>Live overview of MADHYUM leads, people, calling operations and commissions.</p></section><section class="metric-grid"><div class="metric full" onclick="navigate('leads')"><div><div class="label">TOTAL LEADS / INQUIRIES</div><div class="value">${s.total??state.admin.inquiries.length}</div></div><span>→</span></div><div class="metric"><div class="label">NEW</div><div class="value">${s.new??0}</div></div><div class="metric"><div class="label">IN PROGRESS</div><div class="value">${s.inProgress??0}</div></div><div class="metric"><div class="label">CONVERTED</div><div class="value">${s.closed??0}</div></div><div class="metric"><div class="label">VISITORS</div><div class="value">${s.visitors??0}</div></div></section><section class="section-card"><div class="section-head"><h3>Management</h3></div><div class="quick-grid"><button class="quick" onclick="navigate('agents')"><strong>Agents & BDM</strong><small>${state.admin.agents.length} profiles</small></button><button class="quick" onclick="navigate('calling')"><strong>Calling Data</strong><small>Assign & monitor</small></button><button class="quick" onclick="navigate('distribution')"><strong>Distribution</strong><small>Send data/files</small></button><button class="quick" onclick="navigate('adminCommission')"><strong>Commissions</strong><small>Deal payout control</small></button></div></section><section class="section-card"><div class="section-head"><h3>Latest Leads</h3><button class="link" onclick="navigate('leads')">View all</button></div><div class="list">${state.admin.inquiries.slice(0,4).map(l=>leadCard(l,true)).join('')||'<div class="empty">No inquiries.</div>'}</div></section>`;bindLeadButtons(true)}
function renderAdminLeads(){const mc=$('mainContent');mc.innerHTML=`<div class="toolbar"><input class="input" id="adSearch" placeholder="Search ID, name, mobile, Agent ID"><select class="select" id="adWing"><option value="">All requirements</option>${WINGS.map(w=>`<option>${w}</option>`).join('')}</select><select class="select" id="adStatus"><option value="">All statuses</option>${STATUSES.map(s=>`<option>${s}</option>`).join('')}</select></div><div id="adLeadList" class="list"></div>`;const run=()=>{const q=$('adSearch').value.toLowerCase(),w=$('adWing').value,s=$('adStatus').value;const rows=state.admin.inquiries.filter(l=>(!q||[l.inquiryId,l.name,l.mobile,l.agentId].join(' ').toLowerCase().includes(q))&&(!w||l.requirement===w)&&(!s||String(l.status).toUpperCase()===s));$('adLeadList').innerHTML=rows.map(l=>leadCard(l,true)).join('')||'<div class="section-card"><div class="empty">No matching records.</div></div>';bindLeadButtons(true)};$('adSearch').oninput=run;$('adWing').onchange=run;$('adStatus').onchange=run;run()}
async function disposeLead(type,id){if(!confirm(`Move ${id} to Dispose? Original source record stays unchanged.`))return;try{const r=await api('trashRecord',{token:state.token,recordType:type||'WEBSITE',recordId:id});if(!r.success)throw new Error(r.message||'Unable to dispose.');toast('Moved to Dispose');await loadAdminDashboard();renderAdminLeads()}catch(e){toast(e.message)}}
async function loadAgents(show=true){const r=await api('listAgents',{token:state.token});if(!r.success)throw new Error(r.message||'Unable to load agents.');state.admin.agents=Array.isArray(r.agents)?r.agents:(Array.isArray(r.items)?r.items:[]);return r}
function agentCard(a){return `<article class="item-card"><div class="item-top"><div><div class="item-title">${esc(a.name||'')}</div><div class="item-id">${esc(a.agentId||'')}</div></div><span class="status ${String(a.active).toUpperCase()==='YES'?'s-converted':'s-not-interested'}">${esc(a.active||'')}</span></div><div class="item-meta"><span>${esc(a.mobile||'')}</span><span>${String(a.role||'').toUpperCase()==='EMPLOYEE'?'BDM / Employee':'Agent / BDE'}</span>${a.reportingBdmId?`<span>BDM: ${esc(a.reportingBdmId)}</span>`:''}</div><div class="item-actions"><button class="act-gold edit-agent" data-id="${esc(a.agentId)}">Edit</button><button class="act-soft reset-agent" data-id="${esc(a.agentId)}">Reset Password</button>${String(a.active).toUpperCase()==='YES'?`<button class="act-red deactivate-agent" data-id="${esc(a.agentId)}">Deactivate</button>`:''}</div></article>`}
function renderAgents(){$('mainContent').innerHTML=`<section class="section-card"><div class="section-head"><h3>Create Agent / BDM</h3><button class="link" id="createAgentOpen">+ New</button></div><input class="input" id="agentSearchAdmin" placeholder="Search agent, BDM, mobile"></section><div id="agentCards" class="list"></div>`;const run=()=>{const q=$('agentSearchAdmin').value.toLowerCase();const rows=state.admin.agents.filter(a=>[a.agentId,a.name,a.mobile,a.role,a.reportingBdmId].join(' ').toLowerCase().includes(q));$('agentCards').innerHTML=rows.map(agentCard).join('')||'<div class="section-card"><div class="empty">No agents found.</div></div>';bindAgentButtons()};$('agentSearchAdmin').oninput=run;$('createAgentOpen').onclick=openCreateAgent;run()}
function bindAgentButtons(){document.querySelectorAll('.edit-agent').forEach(b=>b.onclick=()=>openEditAgent(b.dataset.id));document.querySelectorAll('.reset-agent').forEach(b=>b.onclick=()=>openResetAgent(b.dataset.id));document.querySelectorAll('.deactivate-agent').forEach(b=>b.onclick=()=>toggleAgentActive(b.dataset.id))}
function bdmOptions(selected=''){return state.admin.agents.filter(a=>String(a.role).toUpperCase()==='EMPLOYEE'&&String(a.active).toUpperCase()==='YES').map(a=>`<option value="${esc(a.agentId)}" ${a.agentId===selected?'selected':''}>${esc(a.agentId+' — '+a.name)}</option>`).join('')}
function openCreateAgent(){openModal('Create Agent / BDM',`<div class="form-grid"><div><label class="field-label">ID (optional)</label><input class="input" id="caId"></div><div><label class="field-label">Name</label><input class="input" id="caName"></div><div><label class="field-label">Mobile</label><input class="input" id="caMobile" maxlength="10"></div><div><label class="field-label">Role</label><select class="select" id="caRole"><option value="AGENT">Agent / BDE</option><option value="Employee">Employee / BDM</option></select></div><div id="caBdmWrap"><label class="field-label">Reporting BDM</label><select class="select" id="caBdm"><option value="">Select BDM</option>${bdmOptions()}</select></div><div><label class="field-label">Password</label><input class="input" id="caPass" type="password" minlength="6"></div></div>`,`<div class="modal-actions"><button class="ghost-btn" onclick="closeModal()">Cancel</button><button class="primary-btn" id="caSave">Create</button></div>`);$('caRole').onchange=()=>{$('caBdmWrap').style.display=String($('caRole').value).toUpperCase()==='AGENT'?'block':'none'};$('caMobile').oninput=e=>e.target.value=cleanPhone(e.target.value);$('caSave').onclick=async()=>{const btn=$('caSave');busy(btn,true,'Creating...');try{const r=await api('createAgent',{token:state.token,agentId:$('caId').value.trim().toUpperCase(),name:$('caName').value.trim(),mobile:cleanPhone($('caMobile').value),role:$('caRole').value,reportingBdmId:String($('caRole').value).toUpperCase()==='AGENT'?$('caBdm').value:'',password:$('caPass').value});if(!r.success)throw new Error(r.message||'Unable to create agent.');toast(`Created ${r.agentId||''}`);closeModal();await loadAgents();renderAgents()}catch(e){toast(e.message)}finally{busy(btn,false)}}}
function openEditAgent(id){const a=state.admin.agents.find(x=>x.agentId===id);if(!a)return;openModal('Edit Agent / BDM',`<div class="form-grid"><div><label class="field-label">Agent ID</label><input class="input" id="eaId" value="${esc(a.agentId)}"></div><div><label class="field-label">Name</label><input class="input" id="eaName" value="${esc(a.name||'')}"></div><div><label class="field-label">Mobile</label><input class="input" id="eaMobile" value="${esc(a.mobile||'')}"></div><div><label class="field-label">Role</label><select class="select" id="eaRole"><option value="AGENT" ${String(a.role).toUpperCase()==='AGENT'?'selected':''}>Agent / BDE</option><option value="Employee" ${String(a.role).toUpperCase()==='EMPLOYEE'?'selected':''}>Employee / BDM</option></select></div><div><label class="field-label">Reporting BDM</label><select class="select" id="eaBdm"><option value="">None</option>${bdmOptions(a.reportingBdmId)}</select></div></div>`,`<div class="modal-actions"><button class="ghost-btn" onclick="closeModal()">Cancel</button><button class="primary-btn" id="eaSave">Save</button></div>`);$('eaSave').onclick=async()=>{const btn=$('eaSave');busy(btn,true,'Saving...');try{const role=$('eaRole').value;const r=await api('updateAgentProfile',{token:state.token,oldAgentId:id,agentId:$('eaId').value.trim().toUpperCase(),name:$('eaName').value.trim(),mobile:cleanPhone($('eaMobile').value),role,reportingBdmId:String(role).toUpperCase()==='AGENT'?$('eaBdm').value:''});if(!r.success)throw new Error(r.message||'Unable to update.');toast('Profile updated');closeModal();await loadAgents();renderAgents()}catch(e){toast(e.message)}finally{busy(btn,false)}}}
function openResetAgent(id){openModal('Reset Password',`<label class="field-label">Agent / BDM ID</label><input class="input" value="${esc(id)}" disabled><label class="field-label">New Password</label><input class="input" id="rpPass" type="password" minlength="6">`,`<div class="modal-actions"><button class="ghost-btn" onclick="closeModal()">Cancel</button><button class="primary-btn" id="rpSave">Reset</button></div>`);$('rpSave').onclick=async()=>{const btn=$('rpSave');busy(btn,true,'Resetting...');try{const r=await api('resetAgentPassword',{token:state.token,agentId:id,password:$('rpPass').value});if(!r.success)throw new Error(r.message||'Unable to reset password.');toast('Password reset');closeModal()}catch(e){toast(e.message)}finally{busy(btn,false)}}}
async function toggleAgentActive(id){const a=state.admin.agents.find(x=>x.agentId===id);if(!a)return;const active=String(a.active).toUpperCase()==='YES';if(active&&!confirm(`Deactivate ${id}?`))return;try{const r=await api('deleteAgent',{token:state.token,agentId:id});if(!r.success)throw new Error(r.message||'Unable to change status.');toast(r.message||'Updated');await loadAgents();renderAgents()}catch(e){toast(e.message)}}
async function loadAdminCalling(){const r=await api('adminCallingData',{token:state.token});if(!r.success)throw new Error(r.message||'Unable to load calling data.');state.admin.calling=Array.isArray(r.items)?r.items:[];state.admin.callRecipients=Array.isArray(r.recipients)?r.recipients:[];if(!state.admin.callRecipients.length){await loadAgents(false);state.admin.callRecipients=state.admin.agents.filter(a=>String(a.active).toUpperCase()==='YES')}return r}
function recipientOptions(selected=''){return state.admin.callRecipients.map(a=>`<option value="${esc(a.agentId)}" ${a.agentId===selected?'selected':''}>${esc(a.agentId+' — '+a.name)}</option>`).join('')}
function renderAdminCalling(){$('mainContent').innerHTML=`<section class="section-card"><div class="section-head"><h3>Assign Calling Data</h3><button class="link" id="openNewCall">+ Add</button></div><input class="input" id="adminCallSearch" placeholder="Search name, mobile, city, source"></section><div id="adminCallList" class="list"></div>`;$('openNewCall').onclick=openNewCalling;const run=()=>{const q=$('adminCallSearch').value.toLowerCase(),rows=state.admin.calling.filter(x=>[x.name,x.mobile,x.city,x.source,x.assignedTo].join(' ').toLowerCase().includes(q));$('adminCallList').innerHTML=rows.map(x=>`<article class="item-card"><div class="item-top"><div><div class="item-title">${esc(x.name||'')}</div><div class="item-id">${esc(x.dataId||'')}</div></div>${statusBadge(x.leadStatus||'NEW')}</div><div class="item-meta"><span>${esc(x.mobile||'')}</span><span>${esc(x.city||'')}</span><span>${esc(x.source||'')}</span></div><div class="form-grid"><div><label class="field-label">Assigned To</label><select class="select ac-assignee">${recipientOptions(x.assignedTo)}</select></div><div><label class="field-label">Call Status</label><select class="select ac-status"><option value="NOT CONNECTED" ${String(x.callStatus).toUpperCase()==='NOT CONNECTED'?'selected':''}>Not Connected</option><option value="CONNECTED" ${String(x.callStatus).toUpperCase()==='CONNECTED'?'selected':''}>Connected</option></select></div><div><label class="field-label">Lead Status</label><select class="select ac-lead">${STATUSES.map(s=>`<option ${s===String(x.leadStatus||'NEW').toUpperCase()?'selected':''}>${s}</option>`).join('')}</select></div><div><label class="field-label">Follow Up</label><input class="input ac-follow" type="date" value="${esc(x.followUpDate||'')}"></div><div class="field-full"><label class="field-label">Remark</label><input class="input ac-remark" value="${esc(x.remark||'')}"></div></div><div class="item-actions">${callActions(x.mobile)}<button class="act-gold save-admin-call" data-id="${esc(x.dataId)}">Save</button></div></article>`).join('')||'<div class="empty">No calling data.</div>';document.querySelectorAll('.save-admin-call').forEach(b=>b.onclick=()=>saveAdminCalling(b.dataset.id,b))};$('adminCallSearch').oninput=run;run()}
function openNewCalling(){openModal('Assign Calling Data',`<div class="form-grid"><div><label class="field-label">Name</label><input class="input" id="ncName"></div><div><label class="field-label">Mobile</label><input class="input" id="ncMobile" maxlength="10"></div><div><label class="field-label">City</label><input class="input" id="ncCity"></div><div><label class="field-label">Source</label><input class="input" id="ncSource"></div><div class="field-full"><label class="field-label">Assign To</label><select class="select" id="ncAssign"><option value="">Select</option>${recipientOptions()}</select></div></div>`,`<div class="modal-actions"><button class="ghost-btn" onclick="closeModal()">Cancel</button><button class="primary-btn" id="ncSave">Assign</button></div>`);$('ncSave').onclick=async()=>{const btn=$('ncSave');busy(btn,true,'Assigning...');try{const r=await api('adminAddCallingData',{token:state.token,name:$('ncName').value.trim(),mobile:cleanPhone($('ncMobile').value),city:$('ncCity').value.trim(),source:$('ncSource').value.trim(),assignedTo:$('ncAssign').value});if(!r.success)throw new Error(r.message||'Unable to assign.');toast('Calling data assigned');closeModal();await loadAdminCalling();renderAdminCalling()}catch(e){toast(e.message)}finally{busy(btn,false)}}}
async function saveAdminCalling(id,btn){const root=btn.closest('.item-card');busy(btn,true,'Saving...');try{const r=await api('adminUpdateCallingData',{token:state.token,dataId:id,assignedTo:root.querySelector('.ac-assignee').value,callStatus:root.querySelector('.ac-status').value,leadStatus:root.querySelector('.ac-lead').value,followUpDate:root.querySelector('.ac-follow').value,remark:root.querySelector('.ac-remark').value.trim()});if(!r.success)throw new Error(r.message||'Unable to save.');toast('Calling data updated');await loadAdminCalling();renderAdminCalling()}catch(e){toast(e.message)}finally{busy(btn,false)}}
function renderAdminMore(){$('mainContent').innerHTML=`<section class="section-card"><div class="quick-grid"><button class="quick" onclick="navigate('distribution')"><strong>⇄ Data Distribution</strong><small>Files & datasets</small></button><button class="quick" onclick="navigate('adminCommission')"><strong>₹ Commissions</strong><small>Deal & payout control</small></button><button class="quick" onclick="navigate('dispose')"><strong>⌫ Dispose</strong><small>Restore hidden records</small></button><button class="quick" onclick="exportAdminCSV()"><strong>⇩ Export Leads</strong><small>CSV download</small></button><button class="quick" onclick="navigate('profile')"><strong>♙ Profile</strong><small>Admin account</small></button></div></section><section class="section-card danger-zone"><button class="danger-btn" style="width:100%" onclick="logout()">Logout</button></section>`}
async function loadAdminDistribution(){const r=await api('adminDataDistribution',{token:state.token});if(!r.success)throw new Error(r.message||'Unable to load distribution.');state.admin.distribution=Array.isArray(r.items)?r.items:[];state.admin.distRecipients=Array.isArray(r.recipients)?r.recipients:[];return r}
function renderAdminDistribution(){const rec=(state.admin.distRecipients?.length?state.admin.distRecipients:state.admin.agents.filter(a=>String(a.active).toUpperCase()==='YES'));$('mainContent').innerHTML=`<section class="section-card"><div class="section-head"><h3>Send Data</h3></div><div class="form-grid"><div><label class="field-label">Recipient</label><select class="select" id="distRec"><option value="">Select Agent / BDM</option>${rec.map(a=>`<option value="${esc(a.agentId)}">${esc(a.agentId+' — '+a.name)}</option>`).join('')}</select></div><div><label class="field-label">Title</label><input class="input" id="distTitle"></div><div class="field-full"><label class="field-label">Details</label><textarea class="textarea" id="distDetails"></textarea></div><div class="field-full"><label class="field-label">Attachment (max 3 MB)</label><input class="input" type="file" id="distFile"></div><div class="field-full"><button class="primary-btn" id="distSend">Send</button></div></div></section><section class="section-card"><div class="section-head"><h3>Distribution History</h3></div><div class="list">${state.admin.distribution.map(sharedCard).join('')||'<div class="empty">No distribution records.</div>'}</div></section>`;$('distSend').onclick=async()=>{const btn=$('distSend');busy(btn,true,'Sending...');try{const f=await filePayload($('distFile').files[0],3);const r=await api('adminSendData',{token:state.token,recipientId:$('distRec').value,title:$('distTitle').value.trim(),details:$('distDetails').value.trim(),file:f,structuredRows:[]});if(!r.success)throw new Error(r.message||'Unable to send.');toast('Data sent');await loadAdminDistribution();renderAdminDistribution()}catch(e){toast(e.message)}finally{busy(btn,false)}};document.querySelectorAll('.open-shared').forEach(b=>b.onclick=()=>openSharedFile('adminGetSharedFile',b.dataset.id))}
async function openSharedFile(action,id){try{const r=await api(action,{token:state.token,distributionId:id});if(!r.success)throw new Error(r.message||'Unable to open file.');const bin=atob(r.base64),bytes=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)bytes[i]=bin.charCodeAt(i);const url=URL.createObjectURL(new Blob([bytes],{type:r.mimeType||'application/octet-stream'}));window.open(url,'_blank');setTimeout(()=>URL.revokeObjectURL(url),60000)}catch(e){toast(e.message)}}
async function loadAdminCommissions(){const r=await api('adminCommissions',{token:state.token});if(!r.success)throw new Error(r.message||'Unable to load commissions.');state.admin.commissions=Array.isArray(r.commissions)?r.commissions:[]}
function renderAdminCommissions(){$('mainContent').innerHTML=`<input class="input" id="comSearch" placeholder="Search lead, customer, LG/BDM/LC" style="margin-bottom:12px"><div id="comList" class="list"></div>`;const run=()=>{const q=$('comSearch').value.toLowerCase(),rows=state.admin.commissions.filter(c=>[c.leadId,c.customerName,c.lgId,c.reportingBdmId,c.lcId].join(' ').toLowerCase().includes(q));$('comList').innerHTML=rows.map(c=>`<article class="item-card"><div class="item-top"><div><div class="item-title">${esc(c.customerName||'')}</div><div class="item-id">${esc(c.leadId||'')}</div></div><span class="money">${money(c.totalCommission)}</span></div><div class="item-meta"><span>${esc(c.wing||'')}</span><span>LG: ${esc(c.lgId||'—')}</span><span>BDM: ${esc(c.reportingBdmId||'—')}</span><span>LC: ${esc(c.lcId||'—')}</span><span>${esc(c.commissionStatus||'')}</span></div><div class="item-actions"><button class="act-gold edit-commission" data-id="${esc(c.leadId)}">Edit Commission</button></div></article>`).join('')||'<div class="empty">No commission records.</div>';document.querySelectorAll('.edit-commission').forEach(b=>b.onclick=()=>openCommission(b.dataset.id))};$('comSearch').oninput=run;run()}
function openCommission(id){const c=state.admin.commissions.find(x=>x.leadId===id);if(!c)return;openModal('Commission',`<div class="form-grid"><div><label class="field-label">Lead ID</label><input class="input" value="${esc(c.leadId)}" disabled></div><div><label class="field-label">Customer</label><input class="input" value="${esc(c.customerName||'')}" disabled></div><div><label class="field-label">LG ID</label><input class="input" id="cmLg" value="${esc(c.lgId||'')}"></div><div><label class="field-label">Reporting BDM</label><input class="input" id="cmBdm" value="${esc(c.reportingBdmId||'')}"></div><div><label class="field-label">LC ID</label><input class="input" id="cmLc" value="${esc(c.lcId||'')}"></div><div><label class="field-label">Deal Value</label><input class="input" id="cmDeal" type="number" value="${esc(c.dealValue||'')}"></div><div><label class="field-label">Total Commission</label><input class="input" id="cmTotal" type="number" value="${esc(c.totalCommission||'')}"></div><div><label class="field-label">LG %</label><input class="input" id="cmLgPct" type="number" value="${esc(c.lgPercent??'')}"></div><div><label class="field-label">LC %</label><input class="input" id="cmLcPct" type="number" value="${esc(c.lcPercent??'')}"></div><div><label class="field-label">Status</label><select class="select" id="cmStatus"><option ${c.commissionStatus==='Pending'?'selected':''}>Pending</option><option ${c.commissionStatus==='Approved'?'selected':''}>Approved</option><option ${c.commissionStatus==='Paid'?'selected':''}>Paid</option></select></div><div><label class="field-label">Payment Date</label><input class="input" id="cmDate" type="date" value="${esc(c.paymentDate||'')}"></div></div>`,`<div class="modal-actions"><button class="ghost-btn" onclick="closeModal()">Cancel</button><button class="primary-btn" id="cmSave">Save</button></div>`);$('cmSave').onclick=async()=>{const btn=$('cmSave');busy(btn,true,'Saving...');try{const r=await api('updateCommission',{token:state.token,leadId:id,lgId:$('cmLg').value.trim().toUpperCase(),reportingBdmId:$('cmBdm').value.trim().toUpperCase(),lcId:$('cmLc').value.trim().toUpperCase(),dealValue:$('cmDeal').value,totalCommission:$('cmTotal').value,lgPercent:$('cmLgPct').value,lcPercent:$('cmLcPct').value,commissionStatus:$('cmStatus').value,paymentDate:$('cmDate').value});if(!r.success)throw new Error(r.message||'Unable to update commission.');toast('Commission saved');closeModal();await loadAdminCommissions();renderAdminCommissions()}catch(e){toast(e.message)}finally{busy(btn,false)}}}
async function loadAdminTrash(){const r=await api('adminTrash',{token:state.token});if(!r.success)throw new Error(r.message||'Unable to load Dispose.');state.admin.trash=Array.isArray(r.records)?r.records:[]}
function renderAdminTrash(){$('mainContent').innerHTML=`<section class="section-card danger-zone"><div class="section-head"><h3>Disposed Records</h3><span class="tiny muted">Original source record remains unchanged</span></div><div class="list">${state.admin.trash.map(r=>`<article class="item-card"><div class="item-top"><div><div class="item-title">${esc(r.name||'')}</div><div class="item-id">${esc(r.inquiryId||r.recordId||'')}</div></div>${statusBadge(r.status)}</div><div class="item-meta"><span>${esc(r.mobile||'')}</span><span>${esc(r.requirement||'')}</span><span>${esc(r.recordType||'')}</span></div><div class="item-actions"><button class="act-green restore-trash" data-id="${esc(r.inquiryId||r.recordId||'')}" data-type="${esc(r.recordType||'WEBSITE')}">Restore</button></div></article>`).join('')||'<div class="empty">Dispose is empty.</div>'}</div></section>`;document.querySelectorAll('.restore-trash').forEach(b=>b.onclick=async()=>{try{const r=await api('restoreTrashRecord',{token:state.token,recordType:b.dataset.type,recordId:b.dataset.id});if(!r.success)throw new Error(r.message||'Unable to restore.');toast('Record restored');await loadAdminTrash();renderAdminTrash()}catch(e){toast(e.message)}})}
window.exportAdminCSV=function(){const rows=state.admin.inquiries;if(!rows.length){toast('No lead data to export');return}const headers=['ID','Date','Time','Name','Mobile','Email','Requirement','Status','Source','Agent ID','Follow Up','Notes'];const csv=[headers,...rows.map(x=>[x.inquiryId,x.date,x.time,x.name,x.mobile,x.email,x.requirement,x.status,x.source,x.agentId,x.followUp,x.notes])].map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='MADHYUM-Leads-'+new Date().toISOString().slice(0,10)+'.csv';a.click();URL.revokeObjectURL(url)};

if('serviceWorker' in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
window.navigate=navigate;window.closeModal=closeModal;window.logout=logout;
if(restoreSession())startApp().catch(()=>logout(true));
